# optiplex-db-restore: body of the script. The header (database lists, consumer units, restore mode)
# is generated by machines/optiplex/services/databases.nix, which also runs shellcheck on the whole.
#
# Variables from the header: PG_DBS (restore order, Synapse last), MARIADB_DBS, SYNAPSE_DB,
# CONSUMER_UNITS, RESTORE_MODE (1 on the optiplex-restore install, 0 on the normal system).

usage() {
  cat <<'USAGE'
optiplex-db-restore: load the Cutover dumps into the shared PostgreSQL and MariaDB servers.

  optiplex-db-restore <dumpdir> [--only <db>]
  optiplex-db-restore --reset <db>
  optiplex-db-restore --help

<dumpdir> is the directory written by machines/optiplex/cutover/arch-db-dumps.sh on Arch
(/mnt/tbssd/cutover-dumps/<UTC timestamp>), or a Backup dump directory. Run as root.

The restore procedure (the Cutover runbook calls this):
  1. The host is installed in restoreMode (nixosConfigurations.optiplex-restore): PostgreSQL,
     MariaDB and their setup oneshots run, the roles and the (empty) databases exist, every
     Kept service is off.
  2. optiplex-db-restore /mnt/tbssd/cutover-dumps/<ts>
     restores all eight databases in this order, small ones first and Synapse last, and checks
     each one. It prints the elapsed time per database.
  3. A normal deploy with restoreMode off (nixos-rebuild --flake .#optiplex). The services start
     against the restored databases and run their own schema migrations.
  4. Keep the dump directory until the Rollback image lifetime ends.
  Never start a service against an empty database.

What it does
  PostgreSQL (as the postgres user, over the socket):
    pg_restore -d <db> --no-owner --no-acl --role=<db> --exit-on-error -j4
    with maintenance_work_mem=1GB and synchronous_commit=off, then vacuumdb --analyze-in-stages.
    The dump must be postgresql/<db>.dump (or <db>.dump) in custom format.
  MariaDB (as root over the socket): mariadb <db> < <db>.sql, also from .sql.gz/.xz/.zst
    (detected by content), so the nightly mysqlBackup dumps work too.
  After each database: no table, sequence, view or function is owned by anyone but the service
  role; matrix-synapse is still C/C; counts/<db>.tsv is re-computed and diffed (skipped with a
  warning when the dump directory has no counts, as with the nightly Backup dumps).

It refuses to run when
  - MANIFEST is missing, or its sha256 sums do not match (a Backup dump directory has none:
    pass --no-manifest to accept that explicitly),
  - a consumer unit is active (matrix-synapse, mautrix-*, gitea, paperless-*, podman-seafile*),
  - a target database already contains objects (the one-shot rule: never restore over data).

--only <db>   restore just that target database (still all the checks)
--reset <db>  drop one target database and recreate it empty (ensureDBOwnership state for
              PostgreSQL, the Synapse oneshot for matrix-synapse, the setup oneshot for MariaDB),
              for a retry after a failed restore. Only on the restoreMode install, only with the
              consumers stopped.
USAGE
}

die() {
  echo "optiplex-db-restore: $*" >&2
  exit 1
}
log() { echo ">> $*"; }
warn() { echo "optiplex-db-restore: WARNING: $*" >&2; }

dumpdir=""
only=""
reset=""
no_manifest=0
while (($#)); do
  case "$1" in
    -h | --help)
      usage
      exit 0
      ;;
    --only)
      only="${2:?--only needs a database name}"
      shift
      ;;
    --reset)
      reset="${2:?--reset needs a database name}"
      shift
      ;;
    --no-manifest) no_manifest=1 ;;
    -*) die "unknown option: $1 (see --help)" ;;
    *)
      [[ -z $dumpdir ]] || die "more than one dump directory given"
      dumpdir="$1"
      ;;
  esac
  shift
done

[[ $EUID -eq 0 ]] || die "run as root"

in_list() { # <name> <list...>
  local n=$1 x
  shift
  for x in "$@"; do [[ $x == "$n" ]] && return 0; done
  return 1
}
is_pg() { in_list "$1" "${PG_DBS[@]}"; }
is_maria() { in_list "$1" "${MARIADB_DBS[@]}"; }

pg() { runuser -u postgres -- psql -X -v ON_ERROR_STOP=1 "$@"; }
maria() { mariadb --protocol=socket -uroot "$@"; }

pg_exists() { [[ "$(pg -d postgres -tAc "select 1 from pg_database where datname = '$1'")" == 1 ]]; }
pg_object_count() { # objects of a user in the database: tables, sequences, views, functions ...
  pg -d "$1" -tAc "select (select count(*) from pg_class c join pg_namespace n on n.oid = c.relnamespace
      where n.nspname <> 'information_schema' and n.nspname !~ '^pg_' and c.relkind in ('r','p','v','m','S','f'))
    + (select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace
      where n.nspname <> 'information_schema' and n.nspname !~ '^pg_')"
}
maria_exists() { [[ -n "$(maria -N -B -e "select 1 from information_schema.schemata where schema_name = '$1'")" ]]; }
maria_table_count() { maria -N -B -e "select count(*) from information_schema.tables where table_schema = '$1'"; }

check_no_consumers() {
  local active
  active="$(systemctl list-units --plain --no-legend --no-pager --state=active,activating,reloading,deactivating "${CONSUMER_UNITS[@]}" | awk '{print $1}')"
  [[ -z $active ]] || die "consumer units are active, stop them first:
$active"
}

# ---------------------------------------------------------------------------------------------
# --reset
# ---------------------------------------------------------------------------------------------
if [[ -n $reset ]]; then
  [[ -z $dumpdir && -z $only ]] || die "--reset takes only a database name"
  ((RESTORE_MODE)) || die "--reset is only allowed on the restoreMode install (this system is in normal mode)"
  check_no_consumers
  if is_pg "$reset"; then
    log "dropping and recreating PostgreSQL database $reset"
    pg -d postgres -c "DROP DATABASE IF EXISTS \"$reset\" WITH (FORCE)"
    if [[ $reset == "$SYNAPSE_DB" ]]; then
      systemctl restart postgresql-synapse-db.service
    else
      pg -d postgres -c "CREATE DATABASE \"$reset\" OWNER \"$reset\""
    fi
    pg_exists "$reset" || die "$reset was not recreated"
  elif is_maria "$reset"; then
    log "dropping and recreating MariaDB database $reset"
    maria -e "DROP DATABASE IF EXISTS \`$reset\`"
    systemctl restart mariadb-seafile-setup.service
    maria_exists "$reset" || die "$reset was not recreated"
  else
    die "unknown database: $reset"
  fi
  log "$reset is empty again"
  exit 0
fi

# ---------------------------------------------------------------------------------------------
# restore
# ---------------------------------------------------------------------------------------------
[[ -n $dumpdir ]] || {
  usage >&2
  exit 2
}
[[ -d $dumpdir ]] || die "$dumpdir is not a directory"
dumpdir="$(cd "$dumpdir" && pwd)"

pg_dir="$dumpdir"
[[ -d $dumpdir/postgresql ]] && pg_dir="$dumpdir/postgresql"
maria_dir="$dumpdir"
[[ -d $dumpdir/mariadb ]] && maria_dir="$dumpdir/mariadb"
counts_dir="$dumpdir/counts"

selected_pg=()
selected_maria=()
if [[ -n $only ]]; then
  if is_pg "$only"; then
    selected_pg=("$only")
  elif is_maria "$only"; then
    selected_maria=("$only")
  else
    die "--only: unknown database $only"
  fi
else
  selected_pg=("${PG_DBS[@]}")
  selected_maria=("${MARIADB_DBS[@]}")
fi

# --- the dump directory: MANIFEST ---------------------------------------------------------------
if [[ -f $dumpdir/MANIFEST ]]; then
  log "verifying $dumpdir/MANIFEST"
  (cd "$dumpdir" && grep -Ev '^(#|$)' MANIFEST | sha256sum --check --quiet --strict -) \
    || die "MANIFEST checksums do not match, the dump directory is damaged or was changed"
  grep -E '^# (date|mode):' "$dumpdir/MANIFEST" | sed 's/^# /   /' || true
elif ((no_manifest)); then
  warn "no MANIFEST in $dumpdir, dump integrity is not verified (--no-manifest)"
else
  die "no MANIFEST in $dumpdir (a Backup dump directory has none: pass --no-manifest)"
fi
in_manifest() { # <path relative to dumpdir>
  [[ ! -f $dumpdir/MANIFEST ]] || grep -Ev '^(#|$)' "$dumpdir/MANIFEST" | awk '{print $2}' | grep -qxF -- "$1"
}

find_pg_dump() { # <db>: print the dump file
  [[ -f $pg_dir/$1.dump ]] && echo "$pg_dir/$1.dump"
}
find_maria_dump() { # <db>
  local f
  for f in "$maria_dir/$1.sql" "$maria_dir/$1.sql.gz" "$maria_dir/$1.sql.xz" "$maria_dir/$1.sql.zst"; do
    [[ -f $f ]] && {
      echo "$f"
      return 0
    }
  done
  return 1
}
rel() { realpath --relative-to="$dumpdir" "$1"; }

# --- all pre-flight checks before anything is touched -----------------------------------------------
check_no_consumers
declare -A dump_of=()
for db in "${selected_pg[@]}"; do
  f="$(find_pg_dump "$db")" || die "no dump for PostgreSQL database $db in $pg_dir ($db.dump)"
  in_manifest "$(rel "$f")" || die "$f is not listed in MANIFEST"
  pg_exists "$db" || die "PostgreSQL database $db does not exist (is postgresql-setup / postgresql-synapse-db done?)"
  n="$(pg_object_count "$db")"
  [[ $n -eq 0 ]] || die "PostgreSQL database $db already contains $n objects: never restore over data (use --reset $db)"
  dump_of[$db]="$f"
done
for db in "${selected_maria[@]}"; do
  f="$(find_maria_dump "$db")" || die "no dump for MariaDB database $db in $maria_dir ($db.sql[.gz|.xz|.zst])"
  in_manifest "$(rel "$f")" || die "$f is not listed in MANIFEST"
  maria_exists "$db" || die "MariaDB database $db does not exist (is mariadb-seafile-setup done?)"
  n="$(maria_table_count "$db")"
  [[ $n -eq 0 ]] || die "MariaDB database $db already contains $n tables: never restore over data (use --reset $db)"
  dump_of[$db]="$f"
done

# --- counts ----------------------------------------------------------------------------------------
pg_counts() { # <db>
  pg -d "$1" -At -F $'\t' <<'SQL' | LC_ALL=C sort
select n.nspname, c.relname,
  (xpath('/row/c/text()', query_to_xml(format('select count(*) as c from %I.%I', n.nspname, c.relname), false, true, '')))[1]::text::bigint
from pg_class c join pg_namespace n on n.oid = c.relnamespace
where c.relkind = 'r' and n.nspname <> 'information_schema' and n.nspname !~ '^pg_'
order by n.nspname collate "C", c.relname collate "C";
SQL
}
maria_counts() { # <db>
  local db=$1 sql="" t
  while IFS= read -r t; do
    [[ -n $t ]] || continue
    sql+="select '$db', '$t', count(*) from \`$db\`.\`$t\`;"$'\n'
  done < <(maria -N -B -e "select table_name from information_schema.tables where table_schema = '$db' and table_type = 'BASE TABLE'" | LC_ALL=C sort)
  [[ -n $sql ]] || return 0
  printf '%s' "$sql" | maria -N -B | LC_ALL=C sort
}
check_counts() { # <db> <pg|maria>
  local db=$1 kind=$2 want="$counts_dir/$1.tsv" got
  if [[ ! -f $want ]]; then
    warn "$db: no counts/$db.tsv in the dump directory, row-count check skipped"
    return 0
  fi
  got="$(mktemp)"
  if [[ $kind == pg ]]; then pg_counts "$db" >"$got"; else maria_counts "$db" >"$got"; fi
  if ! diff -u "$want" "$got"; then
    rm -f "$got"
    die "$db: row counts differ from the dump's counts/$db.tsv (diff above)"
  fi
  log "$db: row counts match counts/$db.tsv ($(wc -l <"$got") tables)"
  rm -f "$got"
}

# --- PostgreSQL ----------------------------------------------------------------------------------------
ensure_postgres_can_read() {
  local f=$1 p
  runuser -u postgres -- test -r "$f" && return 0
  # The dumps are private (umask 077 on Arch). Give the postgres user read access to this tree and
  # search (x) access to the parents it cannot traverse; nothing else is changed.
  setfacl -R -m u:postgres:rX "$dumpdir" || true
  p="$dumpdir"
  while [[ $p != / ]]; do
    p="$(dirname "$p")"
    runuser -u postgres -- test -x "$p" || setfacl -m u:postgres:x "$p" || true
  done
  runuser -u postgres -- test -r "$f" || die "the postgres user cannot read $f"
}

check_pg_owners() { # <db>: nothing in it may be owned by anyone but the role of the same name
  local db=$1 bad
  bad="$(pg -d "$db" -At -v role="$db" <<'SQL'
select 'relation ' || n.nspname || '.' || c.relname || ' owned by ' || pg_get_userbyid(c.relowner)
from pg_class c join pg_namespace n on n.oid = c.relnamespace
where n.nspname <> 'information_schema' and n.nspname !~ '^pg_'
  and c.relowner <> (select oid from pg_roles where rolname = :'role')
  and not exists (select 1 from pg_depend d where d.classid = 'pg_class'::regclass and d.objid = c.oid and d.deptype = 'e')
union all
select 'function ' || n.nspname || '.' || p.proname || ' owned by ' || pg_get_userbyid(p.proowner)
from pg_proc p join pg_namespace n on n.oid = p.pronamespace
where n.nspname <> 'information_schema' and n.nspname !~ '^pg_'
  and p.proowner <> (select oid from pg_roles where rolname = :'role')
  and not exists (select 1 from pg_depend d where d.classid = 'pg_proc'::regclass and d.objid = p.oid and d.deptype = 'e')
union all
select 'type ' || n.nspname || '.' || t.typname || ' owned by ' || pg_get_userbyid(t.typowner)
from pg_type t join pg_namespace n on n.oid = t.typnamespace
where n.nspname <> 'information_schema' and n.nspname !~ '^pg_' and t.typtype in ('e', 'd')
  and t.typowner <> (select oid from pg_roles where rolname = :'role')
  and not exists (select 1 from pg_depend d where d.classid = 'pg_type'::regclass and d.objid = t.oid and d.deptype = 'e')
union all
select 'schema ' || nspname || ' owned by ' || pg_get_userbyid(nspowner)
from pg_namespace
where nspname <> 'information_schema' and nspname !~ '^pg_' and nspname <> 'public'
  and nspowner <> (select oid from pg_roles where rolname = :'role');
SQL
  )"
  [[ -z $bad ]] || die "$db: objects not owned by role $db:
$bad"
  log "$db: every object is owned by role $db"
}

restore_pg() { # <db>
  local db=$1 dump=${dump_of[$1]} start=$SECONDS
  ensure_postgres_can_read "$dump"
  log "$db: pg_restore $(du -h "$dump" | cut -f1) from $dump"
  runuser -u postgres -- env PGOPTIONS='-c maintenance_work_mem=1GB -c synchronous_commit=off' \
    pg_restore -d "$db" --no-owner --no-acl --role="$db" --exit-on-error -j4 "$dump" \
    || die "$db: pg_restore failed (fix the cause, then: optiplex-db-restore --reset $db)"
  log "$db: vacuumdb --analyze-in-stages"
  runuser -u postgres -- vacuumdb --analyze-in-stages -d "$db" >/dev/null
  check_pg_owners "$db"
  if [[ $db == "$SYNAPSE_DB" ]]; then
    local cc
    cc="$(pg -d postgres -tAc "select datcollate || '/' || datctype from pg_database where datname = '$db'")"
    [[ $cc == C/C ]] || die "$db is not C/C but $cc"
    log "$db: still C/C"
  fi
  check_counts "$db" pg
  elapsed[$db]=$((SECONDS - start))
  log "$db: restored in ${elapsed[$db]} s"
}

# --- MariaDB -------------------------------------------------------------------------------------------
decompress_cat() { # <file>: by content, not by name
  local magic
  magic="$(head -c 6 "$1" | od -An -tx1 | tr -d ' \n')"
  case $magic in
    1f8b*) gzip -dc "$1" ;;
    fd377a585a00) xz -dc "$1" ;;
    28b52ffd*) zstd -dc "$1" ;;
    *) cat "$1" ;;
  esac
}

restore_maria() { # <db>
  local db=$1 dump=${dump_of[$1]} start=$SECONDS
  log "$db: mariadb < $dump"
  decompress_cat "$dump" | maria "$db" || die "$db: restore failed (fix the cause, then: optiplex-db-restore --reset $db)"
  check_counts "$db" maria
  elapsed[$db]=$((SECONDS - start))
  log "$db: restored in ${elapsed[$db]} s"
}

declare -A elapsed=()
total=$SECONDS
for db in "${selected_pg[@]}"; do restore_pg "$db"; done
for db in "${selected_maria[@]}"; do restore_maria "$db"; done

echo
echo "== restored from $dumpdir"
for db in "${selected_pg[@]}" "${selected_maria[@]}"; do
  printf '   %-20s %6s s\n' "$db" "${elapsed[$db]}"
done
printf '   %-20s %6s s\n' total $((SECONDS - total))
